sys_security_acl.script:
answer = current.student.user == gs.getUserID();
answer = current.student.user == gs.getUserID();

answer = false;

if (gs.hasRole('x_snc_college_pl_0.admin') || gs.hasRole('x_snc_college_pl_0.interviewer')) {
    answer = true;
} else if (gs.hasRole('x_snc_college_pl_0.student_user')) {
    var app = new GlideRecord('x_snc_college_pl_0.application_user');
    if (app.get(current.application)) {
        if (app.student.user == gs.getUserID()) {
            var iv = new GlideRecord('x_snc_college_pl_0.interview_user');
            iv.addQuery('application', app.sys_id);
            iv.addQuery('result', 'Selected');
            iv.query();

            if (iv.hasNext()) {
                answer = true;
            }
        }
    }
}
